Actionscript.script:
//KODE DI FRAME 1 : Actions

// 1. Hentikan timeline agar tidak auto-play
stop();

// 2. Atur alignment (perataan) ke pojok kiri atas
stage.align = StageAlign.TOP_LEFT;

// 3. Atur scale mode (mode skala)
// Ini kode yang membuat 1920x1080 pas di semua layar
stage.scaleMode = StageScaleMode.SHOW_ALL;


//event button beranda
beranda_btn.addEventListener(MouseEvent.CLICK, changeBeranda);
function changeBeranda(e:MouseEvent):void{
	gotoAndStop(181);
}

//event button materi 1
btn_materi1.addEventListener(MouseEvent.CLICK, changeMateri1);
function changeMateri1(e:MouseEvent):void{
	gotoAndStop(183);
}

